import { Board, Category, Task } from '@/app/types'

export interface BoardSnapshot {
  boards: Board[]
  categories: Category[]
}

// Where board data lives: localStorage for guests, Supabase for signed-in users.
// Every write throws on failure so the caller can tell the user and re-sync.
// IDs are generated by the client and passed in.
export interface BoardDataSource {
  load(): Promise<BoardSnapshot>
  // Returns categories the source created alongside the board (Supabase seeds defaults).
  createBoard(board: Board): Promise<Category[]>
  deleteBoard(boardId: string): Promise<void>
  renameBoard(boardId: string, name: string): Promise<void>
  createTask(task: Task): Promise<void>
  updateTask(taskId: string, updates: Partial<Task>): Promise<void>
  deleteTask(taskId: string): Promise<void>
  createCategory(category: Category): Promise<void>
  // Called with the full state after every change. Local storage persists here; Supabase doesn't need it.
  saveSnapshot?(snapshot: BoardSnapshot): void
  // Notifies when the data changes outside this tab.
  subscribe?(onChange: () => void): () => void
}
